import{_ as t,o as a,c as r,a4 as i}from"./chunks/framework.DMdI2MFY.js";const u=JSON.parse('{"title":"Tape Service","description":"This page gives information about how tape service works using LTO tapes as a medium.","frontmatter":{"title":"Tape Service","category":"Data","outline":1,"description":"This page gives information about how tape service works using LTO tapes as a medium."},"headers":[],"relativePath":"administer-science/data/tape-service/index.md","filePath":"administer-science/data/tape-service/index.md"}'),o={name:"administer-science/data/tape-service/index.md"};function n(s,e,d,c,l,p){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="tape-service" tabindex="-1">Tape service <a class="header-anchor" href="#tape-service" aria-label="Permalink to &quot;Tape service&quot;">​</a></h1><p>Our tape service uses the LTO (Linear Tape-Open) format optimised for high capacity and storage density. LTO tapes provide a reliable way to store your data offline for maximum protection against malicious attacks such as ransomware. The tape service can also be used as a cost-effective way to maintain a backup of your lab data.</p><p>We offer two variants of the service: <strong>tape archive</strong> and <strong>tape backup</strong>. The rest of this page explains the difference, how recovery works, and how to get started.</p><h2 id="tape-archive-vs-tape-backup" tabindex="-1">Tape archive vs tape backup <a class="header-anchor" href="#tape-archive-vs-tape-backup" aria-label="Permalink to &quot;Tape archive vs tape backup&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Tape backup</th><th>Tape archive</th></tr></thead><tbody><tr><td><strong>Intended for</strong></td><td>Supplemental copies of active lab data</td><td>Long-term, passive preservation of data</td></tr><tr><td><strong>What is written</strong></td><td>Full copies of data from predefined storage locations within your lab</td><td>Full copies of the data you designate</td></tr><tr><td><strong>How often</strong></td><td>At scheduled intervals that you specify</td><td>Written once</td></tr><tr><td><strong>Number of tapes</strong></td><td>A single tape</td><td>Two tapes (for increased redundancy)</td></tr><tr><td><strong>Retention</strong></td><td>A period you specify, up to 10 years</td><td>A period you specify, up to 10 years</td></tr><tr><td><strong>Cost model</strong></td><td>Metered daily on the cumulative terabytes written across the retention period</td><td>A one-time charge per order, for the terabytes written</td></tr></tbody></table><p>Both variants maintain the same high level of data integrity and security.</p><h2 id="what-you-need-to-decide" tabindex="-1">What you need to decide <a class="header-anchor" href="#what-you-need-to-decide" aria-label="Permalink to &quot;What you need to decide&quot;">​</a></h2><p>As a Lab leader, you are responsible for:</p><ul><li><strong>Identifying the data</strong> in your lab that should be written to tape.</li><li><strong>Specifying the retention length</strong> - how long the data should be kept, up to a maximum of 10 years.</li><li><strong>Specifying the interval</strong> for tape backup jobs - how often a fresh full copy is written.</li></ul><p>We&#39;re responsible for the technical side:</p><ul><li>configuration and maintenance of the tape systems,</li><li>encryption keys,</li><li>tape writes,</li><li>preservation,</li><li>data retrieval,</li><li>destruction of tapes.</li></ul><p>If a lab subscription is terminated before the retention period expires, responsibility for the tape data passes to the service center the lab is attached to.</p><h2 id="retrieval" tabindex="-1">Retrieval <a class="header-anchor" href="#retrieval" aria-label="Permalink to &quot;Retrieval&quot;">​</a></h2><p>You can order data retrieval at any time during the retention period.</p><div class="warning custom-block"><p class="custom-block-title">Retrieval is not instant</p><p>The retrieval process includes manual steps and may involve tapes held off-site and offline, so requests can take an extended period to complete. Plan accordingly. Tape is not a substitute for a working copy of data you need on short notice.</p></div><p>Within that, recovery from a tape backup is usually faster than from a tape archive, since archive tapes are more likely to have been moved off-site and need to be returned to the library manually. Several factors can affect the timeline in either case.</p><h2 id="storage-distribution-and-destruction" tabindex="-1">Storage, distribution and destruction <a class="header-anchor" href="#storage-distribution-and-destruction" aria-label="Permalink to &quot;Storage, distribution and destruction&quot;">​</a></h2><p>Tapes may be moved outside our data centers under a documented chain-of-custody procedure. Off-site and offline tapes are stored in protected zones in Trondheim, Norway, designed to withstand fire for up to one hour.</p><div class="danger custom-block"><p class="custom-block-title">Data is destroyed when retention expires</p><p>After the retention period expires, data is irrevocably destroyed without notification. Make sure the retention length you specify actually covers how long you need the data.</p></div><h2 id="cost" tabindex="-1">Cost <a class="header-anchor" href="#cost" aria-label="Permalink to &quot;Cost&quot;">​</a></h2><p>The cost per terabyte for both types is listed in the <a href="/administer-science/prices/pricelist">price list</a>. The two are metered differently, and the difference matters:</p><ul><li><strong>Tape archive</strong> is a one-time charge per order, based on the total terabytes written.</li><li><strong>Tape backup</strong> is metered daily, based on the total terabytes written across the retention period. Because each job writes a full copy, the metered volume grows with every interval.</li></ul><p>The meter starts when the first data is written and ends when the retention period expires, or when we receive a termination request for the tape order. All meters end on the date we receive a termination notice for the Services Agreement. Consumption is billed the following quarter.</p><div class="tip custom-block"><p class="custom-block-title">Watch the interval</p><p>Frequent intervals combined with long retention multiply quickly. If the data is not changing, tape archive is usually the cheaper choice.</p></div><h2 id="why-we-use-lto-tape" tabindex="-1">Why we use LTO tape <a class="header-anchor" href="#why-we-use-lto-tape" aria-label="Permalink to &quot;Why we use LTO tape&quot;">​</a></h2><p>LTO is an open format maintained by a consortium of manufacturers rather than a single vendor, so drives and media remain available and compatible across the long timescales this service is built for. Two properties make it a good fit:</p><ul><li><strong>Very low error rates.</strong> The LTO specification permits at most one unrecoverable bit error per 10<sup>19</sup> bits written - roughly four orders of magnitude better than a typical hard drive - achieved through error correction built into the drives. Full specifications are published by the <a href="https://www.lto.org/" target="_blank" rel="noreferrer">LTO Consortium</a>.</li><li><strong>It can be taken offline.</strong> A tape on a shelf is not reachable over the network, which is what makes tape effective against ransomware and similar attacks.</li></ul><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ul><li><strong>Encryption.</strong> Tapes are written encrypted, and HUNT Cloud manages the encryption keys.</li><li><strong>Written once.</strong> LTO supports WORM (Write Once, Read Many), so data cannot be altered or deleted after it is written. Archive data is written once and not changed afterwards.</li><li><strong>Offline and off-site.</strong> Tapes are kept offline in protected zones, inaccessible from the internet. Even if your lab systems are compromised, the data on tape stays safe.</li></ul><h2 id="tape-service-software" tabindex="-1">Tape service software <a class="header-anchor" href="#tape-service-software" aria-label="Permalink to &quot;Tape service software&quot;">​</a></h2><p>You can read more on bacula <a href="https://en.wikipedia.org/wiki/Bacula" target="_blank" rel="noreferrer">here</a>. Official documentation of bacula can be found <a href="https://docs.baculasystems.com/index.html" target="_blank" rel="noreferrer">here</a></p><h2 id="how-can-i-get-my-data-on-tape" tabindex="-1">How can I get my data on tape? <a class="header-anchor" href="#how-can-i-get-my-data-on-tape" aria-label="Permalink to &quot;How can I get my data on tape?&quot;">​</a></h2><p>You can start by visiting our <a href="/administer-science/service-desk/lab-orders#tape-backup">service desk</a>.</p>',33)])])}const f=t(o,[["render",n]]);export{u as __pageData,f as default};
